// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;
import static org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFactorizedQuoteTest.row;

import org.eclipse.rdf4j.common.order.StatementOrder;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeCostVector.Feature;
import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeFanOutFactsTest.StatsSource;
import org.junit.jupiter.api.Test;

/**
 * The leapfrog join is quoted level by level: a frontier per member and level, computed once per distinct prefix up to
 * its deepest key (constant frontiers once), intersected by a galloping merge, with the search entering the next level
 * once per surviving value.
 */
class LmdbNativeLeapfrogQuoteTest {

	private static final long P = 7L;
	private static final int A = 0, B = 1, C = 2;

	private static StatsSource triangleStats(boolean served) {
		return new StatsSource(100_000L).predicate(P, 3D, 3_000L)
				.predicateByObject(P, 3D, 3_000L)
				.adjacencyServed(served);
	}

	/** {@code spoc} only: an index prefix covers the leading bound fields in subject, predicate, object order. */
	private static NativeLmdbQuerySource.IndexAccessProfile spocProfile(long entries) {
		int[][] prefixes = new int[StatementOrder.values().length + 1][16];
		for (int[] prefixRow : prefixes) {
			for (int mask = 0; mask < 16; mask++) {
				int prefix = 0;
				for (int bit = 1; bit <= 8 && (mask & bit) != 0; bit <<= 1) {
					prefix |= bit;
				}
				prefixRow[mask] = prefix;
			}
		}
		return new NativeLmdbQuerySource.IndexAccessProfile(entries, 1, prefixes, false, -1L, -1L, -1L);
	}

	private static PatternPlan edge(int subjectSlot, int objectSlot, NativeLmdbQuerySource.IndexAccessProfile profile) {
		return new PatternPlan(Term.slot(subjectSlot), Term.constant(P), Term.slot(objectSlot), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, null, "", null, 9_000D, profile);
	}

	private static PatternPlan[] triangle(NativeLmdbQuerySource.IndexAccessProfile profile) {
		return new PatternPlan[] { edge(A, B, profile), edge(B, C, profile), edge(C, A, profile) };
	}

	private static LmdbNativeLeapfrogQuote.Quote quote(StatsSource source,
			NativeLmdbQuerySource.IndexAccessProfile profile) {
		return quote(source, profile, 1D);
	}

	private static LmdbNativeLeapfrogQuote.Quote quote(StatsSource source,
			NativeLmdbQuerySource.IndexAccessProfile profile, double entries) {
		return LmdbNativeLeapfrogQuote.core(triangle(profile), new MaskedFilter[0], row(source), 0L, entries);
	}

	@Test
	void frontiersWithoutBoundTermsArePaidOncePerOpenNotPerEntry() {
		LmdbNativeLeapfrogQuote.Quote once = quote(triangleStats(true),
				LmdbNativeFactorizedQuoteTest.coveringProfile(100_000L), 1D);
		LmdbNativeLeapfrogQuote.Quote thrice = quote(triangleStats(true),
				LmdbNativeFactorizedQuoteTest.coveringProfile(100_000L), 3D);
		// the three key enumerations depend on no binding: the plan's frontier cache serves every entry
		assertThat(thrice.vector().expected(Feature.SCANNED_ROW))
				.isEqualTo(9_000D + 3D * (9_000D + 27_000D + 9_000D));
		// keyed frontiers are recomputed per entry
		assertThat(thrice.vector().expected(Feature.INDEX_SEEK))
				.isEqualTo(3D * once.vector().expected(Feature.INDEX_SEEK));
		assertThat(thrice.rows()).isCloseTo(3D * once.rows(), within(1e-9));
	}

	@Test
	void servedFrontiersAreBoundOncePerDistinctKeyAndConstantOnesOnce() {
		LmdbNativeLeapfrogQuote.Quote quote = quote(triangleStats(true),
				LmdbNativeFactorizedQuoteTest.coveringProfile(100_000L));
		LmdbNativeCostVector vector = quote.vector();
		// level ?a: two key enumerations (3000 each, once); level ?b: ?a's run bound 3000 times (3 rows each) and
		// ?b's key enumeration once; level ?c: ?b's run bound 9000 times and ?a's in-run 3000 times (it changes only
		// when ?a does)
		assertThat(vector.expected(Feature.INDEX_SEEK)).isEqualTo(3_000D + 9_000D + 3_000D);
		assertThat(vector.expected(Feature.SCANNED_ROW))
				.isEqualTo(6_000D + 9_000D + 3_000D + 27_000D + 9_000D);
		assertThat(vector.expected(Feature.SORT_N_LOG2_N)).isZero();
		// the merge walks the smallest frontier at every entry: 3000, then 3 at each of 3000 and 9000 entries
		assertThat(vector.expected(Feature.MEMBERSHIP_TEST)).isEqualTo(3_000D + 9_000D + 27_000D);
		// 9000 (?a, ?b) prefixes, 3 candidates for ?c from each side out of 3000: 27 triangles
		assertThat(quote.rows()).isCloseTo(27D, within(1e-9));
	}

	@Test
	void lmdbFrontiersCollectAndSortTheirRows() {
		LmdbNativeLeapfrogQuote.Quote quote = quote(triangleStats(false),
				LmdbNativeFactorizedQuoteTest.coveringProfile(100_000L));
		LmdbNativeCostVector vector = quote.vector();
		assertThat(vector.expected(Feature.SORT_N_LOG2_N)).isGreaterThan(0D);
		// the two constant scans and the key-free scan seek once each; the keyed probes seek per distinct key
		assertThat(vector.expected(Feature.INDEX_SEEK)).isEqualTo(3D + 3_000D + 9_000D + 3_000D);
		assertThat(quote.rows()).isCloseTo(27D, within(1e-9));
	}

	@Test
	void aFrontierWithoutALeadingIndexWalksTheWholeRange() {
		LmdbNativeLeapfrogQuote.Quote quote = quote(triangleStats(false), spocProfile(100_000L));
		// ?c P ?a with ?a bound is an object-bound probe: on spoc only, each of its 3000 computations sweeps the
		// predicate's range (measured 2026-11-02: 17 to 78 times slower than a probe chain on spoc-only stores)
		assertThat(quote.vector().expected(Feature.SCANNED_ROW)).isGreaterThanOrEqualTo(3_000D * 100_000D);
	}
}
